import{_ as e,c as t,o as r,b2 as n}from"./chunks/framework.CUhoHPxN.js";const h=JSON.parse('{"title":"C7ExcelDownload（C7 Excel / Blob 下载按钮）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-08-c7-excel-download-design.md","filePath":"superpowers/specs/2026-05-08-c7-excel-download-design.md"}'),d={name:"superpowers/specs/2026-05-08-c7-excel-download-design.md"};function s(c,o,g,a,l,i){return r(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="c7exceldownload-c7-excel-blob-下载按钮-设计说明" tabindex="-1">C7ExcelDownload（C7 Excel / Blob 下载按钮）设计说明 <a class="header-anchor vp-link" href="#c7exceldownload-c7-excel-blob-下载按钮-设计说明" aria-label="Permalink to &quot;C7ExcelDownload（C7 Excel / Blob 下载按钮）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-08<br><strong>状态</strong>：已定稿（经 brainstorming 澄清与「确认定稿」）<br><strong>依据</strong>：<code>原始需求/前端/C7Excel下载.md</code> + Q&amp;A 结论（<strong>1B、2A、3A、4A、5A、6A</strong>）及实现路径 <strong>路径 1</strong>（单文件 <code>index.vue</code> + 必要时同文件内纯函数）</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><ul><li><strong>背景</strong>：导出接口通常返回 <strong>Blob</strong>，文件名可能在响应头 <strong><code>Content-Disposition</code></strong> 中；页面需要统一的下载按钮、下载触发、进行中状态与错误提示。</li><li><strong>目标</strong>：提供 <strong><code>C7ExcelDownload</code></strong>：点击执行 <strong><code>downloadFn</code></strong>，解析文件名并触发浏览器下载，管理 <strong><code>downloading</code></strong>，失败时 <strong><code>notify</code> + <code>emit(&#39;error&#39;)</code></strong>；成功 <strong><code>emit(&#39;success&#39;, fileName)</code></strong>。</li><li><strong>非目标</strong>：不强制替换全局 <strong><code>$download</code> / <code>download()</code></strong> 的既有行为；不限定仅 Excel 扩展名（组件名为系列命名，<strong>6A</strong>）；不负责业务查询参数与 URL 拼装（由业务 API / <code>downloadRequest</code> 等负责）。</li></ul><hr><h2 id="_2-命名、边界与落点" tabindex="-1">2. 命名、边界与落点 <a class="header-anchor vp-link" href="#_2-命名、边界与落点" aria-label="Permalink to &quot;2. 命名、边界与落点&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td><strong>对外组件名</strong></td><td><strong><code>C7ExcelDownload</code></strong></td></tr><tr><td><strong>目录</strong></td><td><strong><code>quick-ui/src/packages/C7ExcelDownload/index.vue</code></strong></td></tr><tr><td><strong>实现形态</strong></td><td><strong>单文件组件</strong>；<code>Content-Disposition</code> 解析、<code>objectURL</code> 触发下载等可在同文件底部以 <strong>纯函数</strong> 形式组织，避免过早抽包。若后续非按钮场景也要复用，再评估 <strong><code>useC7BlobDownload</code></strong>（<strong>本期不做</strong>）。</td></tr><tr><td><strong>全局注册</strong></td><td>在 <strong><code>quick-ui/src/packages/index.js</code></strong> 中 <strong><code>export</code></strong> 与 <strong><code>installPackages</code></strong> 注册，与其它 C7 一致。</td></tr></tbody></table></div><p><strong>职责</strong>：触发 <strong><code>downloadFn</code></strong>；归一返回值；按优先级解析文件名；校验 Blob（含 JSON 错误体）；<code>objectURL</code> + <code>&lt;a download&gt;</code> 下载并 <strong><code>revokeObjectURL</code></strong>；<strong><code>downloading</code></strong> 与 <strong><code>v-model:downloading</code></strong>；默认 <strong><code>ElMessage</code></strong> 错误提示。</p><p><strong>不负责</strong>：axios 实例的全局策略改造（除下文约定的 <strong>可选 headers 返回</strong> 外）；未传入 <strong><code>downloadFn</code></strong> 时的占位行为（实现时若 <code>downloadFn</code> 缺失可 <code>console.warn</code> + no-op，以代码评审为准）。</p><hr><h2 id="_3-与-downloadrequest-request-的关系-1b" tabindex="-1">3. 与 <code>downloadRequest</code> / <code>request</code> 的关系（<strong>1B</strong>） <a class="header-anchor vp-link" href="#_3-与-downloadrequest-request-的关系-1b" aria-label="Permalink to &quot;3. 与 `downloadRequest` / `request` 的关系（**1B**）&quot;">​</a></h2><ul><li><strong>分工</strong>：业务侧继续使用 <strong><code>downloadRequest</code></strong>（或等价 axios 调用）发起导出请求；<strong><code>downloadFn</code> 由父组件传入</strong>，组件负责点击、文件名解析、触发下载与状态。</li><li><strong>现状与缺口</strong>：当前响应拦截器在 <strong><code>responseType === &#39;blob&#39;</code></strong> 时 <strong><code>return res.data</code></strong>，调用方默认<strong>仅得 <code>Blob</code></strong>，<strong>无法</strong>读取 <strong><code>Content-Disposition</code></strong>，因此文件名优先级 <strong>第 4 节之 2）、3）</strong> 在无补充手段时不可用。</li><li><strong>实现阶段要求</strong>（写入实现计划）：在 <strong><code>quick-ui/src/utils/request.js</code></strong>（或同层薄封装）增加<strong>向后兼容</strong>能力，使调用方可选拿到 <strong><code>{ data: Blob, headers }</code></strong>，例如： <ul><li><strong><code>axios</code> 请求 <code>config</code> 显式开关</strong>（如 <strong><code>returnBlobWithHeaders: true</code></strong>），拦截器在 blob 分支：若开启则 <strong><code>return { data: res.data, headers: res.headers }</code></strong>，否则仍 <strong><code>return res.data</code></strong>；<strong>或</strong></li><li>新增 <strong><code>downloadRequestWithHeaders(url, params, config)</code></strong>，与 <strong><code>downloadRequest</code></strong> 同鉴权、同 <strong><code>baseURL</code></strong>，仅返回形态含 <strong>headers</strong>。</li></ul></li><li><strong>组件归一</strong>：<code>downloadFn</code> 的 resolve 值支持 <strong><code>Blob</code></strong> 或 <strong><code>{ data: Blob; headers?: Record&lt;string, unknown&gt; }</code></strong>（headers 以实现时 axios 类型为准）；若仅有 <strong><code>Blob</code></strong>，文件名仅依赖 <strong><code>fileName</code> prop</strong> 与 <strong><code>defaultFileName</code></strong>（<strong>第 4 节步骤 1、4</strong>）。</li></ul><hr><h2 id="_4-文件名解析优先级-与原始需求一致" tabindex="-1">4. 文件名解析优先级（与原始需求一致） <a class="header-anchor vp-link" href="#_4-文件名解析优先级-与原始需求一致" aria-label="Permalink to &quot;4. 文件名解析优先级（与原始需求一致）&quot;">​</a></h2><ol><li><strong><code>fileName</code> prop</strong>：非空（trim 后）则直接使用，<strong>不再</strong>解析响应头。</li><li><strong><code>Content-Disposition</code></strong> 中的 <strong><code>filename*=UTF-8&#39;&#39;...</code></strong>（RFC 5987）：对 <code>&#39;&#39;</code> 后片段做 <strong><code>decodeURIComponent</code></strong>（解析失败则顺延下一项）。</li><li><strong><code>filename=&quot;...&quot;</code></strong> 或 <strong><code>filename=...</code></strong>（无引号时按 token 规则截取，实现计划写清边界）。</li><li><strong><code>defaultFileName</code></strong>：在 <strong>1～3</strong> 均未得到有效文件名时使用。</li></ol><p>若 <strong>1～4</strong> 均无法得到可用文件名：<strong>不触发下载</strong>，<strong><code>emit(&#39;error&#39;, err)</code></strong>（<code>err</code> 可为 <strong><code>Error</code></strong> 或项目约定类型），<strong><code>notify(&#39;error&#39;, message)</code></strong>（默认 <strong><code>ElMessage.error</code></strong>，文案在实现计划中固定一句中文即可）。</p><hr><h2 id="_5-downloadfn、事件与-downloading-5a" tabindex="-1">5. <code>downloadFn</code>、事件与 <code>downloading</code>（<strong>5A</strong>） <a class="header-anchor vp-link" href="#_5-downloadfn、事件与-downloading-5a" aria-label="Permalink to &quot;5. `downloadFn`、事件与 `downloading`（**5A**）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td><strong><code>downloadFn</code></strong></td><td><strong><code>() =&gt; Promise&lt;Blob | { data: Blob; headers?: ... }&gt;</code></strong>；由业务封装 <strong><code>downloadRequest</code> / 带 headers 的变体</strong>。</td></tr><tr><td><strong><code>success</code></strong></td><td><strong><code>emit(&#39;success&#39;, fileName: string)</code></strong>，在浏览器下载链成功触发后（与 <strong><code>revokeObjectURL</code></strong> 顺序以实现计划为准，须保证 <code>fileName</code> 为最终采用的字符串）。</td></tr><tr><td><strong><code>error</code></strong></td><td><strong><code>emit(&#39;error&#39;, err: unknown)</code></strong>；凡 <strong><code>downloadFn</code> reject</strong>、JSON 伪装 Blob、无可用文件名、创建 URL / 点击链异常等均触发。</td></tr><tr><td><strong><code>downloading</code></strong></td><td>内部 <strong><code>ref(false)</code></strong>；在 <strong><code>downloadFn</code> 调用开始时</strong> 置为 <strong><code>true</code></strong>，在 <strong><code>finally</code></strong> 中置为 <strong><code>false</code></strong>。</td></tr><tr><td><strong>对外同步</strong></td><td><strong><code>v-model:downloading</code></strong>（<strong><code>downloading</code> prop + <code>update:downloading</code></strong>），父组件可读写过载态；组件内部开始下载时仍应 <strong><code>emit(&#39;update:downloading&#39;, true)</code></strong> 等，与 Vue 3 习惯一致。</td></tr><tr><td><strong>重复点击</strong></td><td><strong><code>downloading === true</code></strong> 时点击 <strong>no-op</strong>（不再次调用 <strong><code>downloadFn</code></strong>）（<strong>5A</strong>）。</td></tr></tbody></table></div><hr><h2 id="_6-blob-校验与-json-错误体-4a" tabindex="-1">6. Blob 校验与 JSON 错误体（<strong>4A</strong>） <a class="header-anchor vp-link" href="#_6-blob-校验与-json-错误体-4a" aria-label="Permalink to &quot;6. Blob 校验与 JSON 错误体（**4A**）&quot;">​</a></h2><ul><li>得到 <strong><code>Blob</code></strong> 后使用与 <strong><code>blobValidate</code></strong>（<strong><code>@/utils/ruoyi</code></strong>）<strong>等价</strong>的判定：<strong><code>blob.type !== &#39;application/json&#39;</code></strong> 视为可尝试当文件下载；否则视为错误响应体。</li><li>若类型为 <strong><code>application/json</code></strong>：<strong><code>await blob.text()</code></strong> → <strong><code>JSON.parse</code></strong>（<strong>try/catch</strong>）→ 优先取后端 <strong><code>msg</code></strong>，其次与 <strong><code>download()</code></strong>（<strong><code>request.js</code></strong>）对齐的错误码表（<strong><code>errorCode</code></strong>）若可复用则复用；<strong><code>notify(&#39;error&#39;, message)</code></strong> + <strong><code>emit(&#39;error&#39;, err)</code></strong>；<strong>不</strong>创建 <strong><code>objectURL</code></strong>、<strong>不</strong>触发下载。</li><li><strong><code>downloadFn</code> reject</strong>：<strong><code>notify(&#39;error&#39;, message)</code></strong>（默认将 <strong><code>err</code></strong> 转为可读字符串，与现有 axios 错误提示风格协调即可）+ <strong><code>emit(&#39;error&#39;, err)</code></strong>。</li></ul><hr><h2 id="_7-下载机制与资源释放" tabindex="-1">7. 下载机制与资源释放 <a class="header-anchor vp-link" href="#_7-下载机制与资源释放" aria-label="Permalink to &quot;7. 下载机制与资源释放&quot;">​</a></h2><ul><li><strong><code>URL.createObjectURL(blob)</code></strong> + 内存中创建 <strong><code>&lt;a&gt;</code></strong>，设置 <strong><code>download</code></strong> 为 <strong>第 4 节</strong> 解析得到的文件名（若浏览器忽略 <code>download</code> 仍可能以 URL 展示，以浏览器行为为准），<strong>程序化 <code>click()</code></strong>。</li><li><strong><code>URL.revokeObjectURL</code></strong>：在 <strong><code>click()</code></strong> 之后使用 <strong><code>requestAnimationFrame</code> 或 <code>setTimeout(0)</code></strong> 延迟释放，避免部分浏览器未读完即 revoke。</li></ul><hr><h2 id="_8-ui-2a" tabindex="-1">8. UI（<strong>2A</strong>） <a class="header-anchor vp-link" href="#_8-ui-2a" aria-label="Permalink to &quot;8. UI（**2A**）&quot;">​</a></h2><ul><li>默认使用 <strong><code>ElButton</code></strong>；<strong><code>:loading=&quot;downloading&quot;</code></strong>（或与 Element <strong><code>loading</code></strong> 语义对齐）。</li><li>常用展示属性（<strong><code>type</code> / <code>size</code> / <code>disabled</code> / <code>plain</code> / <code>round</code> / <code>link</code> 等</strong>）通过 <strong><code>v-bind=&quot;$attrs&quot;</code></strong> 透传，<strong><code>inheritAttrs: false</code></strong> 时在根 <strong><code>ElButton</code></strong> 上合并 <strong><code>class</code> / <code>style</code></strong>（实现计划二选一，避免重复绑定内部事件名即可）。</li><li><strong>默认插槽</strong>：按钮文案；无插槽时可用默认文案如 <strong>「导出」</strong>（实现计划与 i18n 策略以代码评审为准，设计不强制词条文件）。</li></ul><hr><h2 id="_9-notify-与默认行为-3a" tabindex="-1">9. <code>notify</code> 与默认行为（<strong>3A</strong>） <a class="header-anchor vp-link" href="#_9-notify-与默认行为-3a" aria-label="Permalink to &quot;9. `notify` 与默认行为（**3A**）&quot;">​</a></h2><ul><li><strong><code>notify?: (type: &#39;success&#39; \\| &#39;error&#39; \\| &#39;warning&#39; \\| &#39;info&#39;, message: string) =&gt; void</code></strong>。</li><li>未传入时，错误路径使用 <strong><code>ElMessage</code></strong>（<strong><code>ElMessage.error</code> 等</strong>）与现有 <strong><code>download()</code></strong> 失败提示习惯一致。</li></ul><hr><h2 id="_10-验收与测试建议" tabindex="-1">10. 验收与测试建议 <a class="header-anchor vp-link" href="#_10-验收与测试建议" aria-label="Permalink to &quot;10. 验收与测试建议&quot;">​</a></h2><ul><li><strong><code>downloadFn</code> 仅返回 <code>Blob</code></strong> + <strong><code>fileName</code> 或 <code>defaultFileName</code></strong> → 成功下载，文件名为预期。</li><li><strong><code>downloadFn</code> 返回 <code>{ data, headers }</code></strong>，<strong><code>Content-Disposition</code></strong> 含 <strong><code>filename*</code></strong> / <strong><code>filename=</code></strong> → 本地文件名符合 <strong>第 4 节</strong> 优先级。</li><li><strong>返回 <code>application/json</code> 的 Blob</strong> → 不下载，有 <strong><code>error</code> + notify</strong>。</li><li><strong><code>downloading</code> 为 true</strong> 时再次点击 → <strong><code>downloadFn</code> 调用次数不增加</strong>。</li></ul><hr><h2 id="_11-后续流程" tabindex="-1">11. 后续流程 <a class="header-anchor vp-link" href="#_11-后续流程" aria-label="Permalink to &quot;11. 后续流程&quot;">​</a></h2><ul><li>实现前：由 <strong><code>writing-plans</code></strong> 产出分步实现计划（含 <strong><code>request.js</code> 扩展点</strong> 与组件联调）。</li><li>本文档经用户审阅无修改后，再进入编码阶段。</li></ul>',38)])])}const b=e(d,[["render",s]]);export{h as __pageData,b as default};
